def unique(xs): return list(dict.fromkeys(xs))
def page(xs,n,size):
    if n<0 or size<=0: raise ValueError("invalid page")
    return xs[n*size:(n+1)*size]

acceptance:
from app import unique,page; assert unique([2,1,2])==[2,1]; assert page([1,2,3],1,2)==[3]
try: page([],0,0)
except ValueError: pass
else: raise AssertionError("invalid size accepted")

